@startuml

enum AttendanceStatus {
  Yes
  Maybe
  No
}

enum TaskStatus {
  ToBeDone
  Done
  NotApplicable
}

class Organizer {
  + FirstName : string
  + LastName : string
  + EmailAddress : string
  + Password : string
  + PostalAddress : string
  + PhoneNumber : string
}

class Attendee {
  + FirstName : string
  + LastName : string
  + EmailAddress : string
  + Password : string
}

class Event {
  + StartDateTime : datetime
  + EndDateTime : datetime
  + Occasion : string
}

class EventType {
  + Name : string
}

class Location {
  + Name : string
  + Address : string
}

class Task {
  + Description : string
}

class ChecklistItem {
  + Status : TaskStatus
}

class AssignedTask {
  + Status : TaskStatus
}

Organizer "1..*" -- "0..*" Event : organizes
Organizer "0..*" -- "0..*" Attendee : invites
Attendee "0..*" -- "0..*" Event : attends
Event "*" -- "1" EventType : is of type
Event "*" -- "1" Location : held at
Event "1" *-- "*" ChecklistItem : has
ChecklistItem "1" -- "1" Task : refers to
ChecklistItem "0..1" -- "0..1" Attendee : assigned to
ChecklistItem "0..1" -- "0..1" AssignedTask : becomes

@enduml

